-- Study Abroad country content, BATCH 8: Cyprus, Malta, Lithuania, Latvia, Estonia.
-- Researched from public sources in November 2026 (see backend/TODO_country_tables.md for what still needs checking).
-- Text blocks fill the columns on countries; subject / course rows are linked to subjects / specializations
-- (country_sections.subject_id / specialization_id) so the website links them to those pages.
-- Replaces the earlier '[Sample]' / '[Placeholder]' rows of these 5 countries. Safe to re-run.
-- Requires alembic revision e6a3c9d1f4b7 (alembic upgrade head).
BEGIN;
DELETE FROM country_sections WHERE country_id IN (SELECT id FROM countries WHERE slug IN ('cyprus', 'malta', 'lithuania', 'latvia', 'estonia'));
UPDATE countries SET why_title = 'Why study in Cyprus?', why_body = '<p>Cyprus is an EU country with English-taught degrees, a warm climate and lower costs than most of Western Europe. It is popular for tourism, business, shipping, health and engineering programmes.</p><ul><li>English-taught degrees at public and private universities</li><li>EU-recognised qualifications in a Mediterranean setting</li><li>Strong tourism, shipping and business sectors</li><li>Lower living costs than many EU countries</li></ul>', visa_title = 'Student visa and residence permit', visa_body = '<p>Non-EU students need an <strong>entry permit or student visa</strong> approved by the Cyprus Migration Department, and then a <strong>residence permit</strong> after arrival. The university normally lodges the application and arranges the first approval.</p><ul><li>Admission letter and proof of tuition payment (the Migration Department will not accept applications without evidence of payment)</li><li>Proof of funds: students may have to place a fixed deposit; confirm the amount with your university</li><li>Private health insurance valid in Cyprus (reported at about €150-€350 a year)</li><li>Criminal record certificate and medical test</li><li>Apply for the residence permit at the Civil Registry and Migration Department within 10 days of arrival</li><li>Residence and registration fees: reported at about €140-€200 in total</li><li>Work: non-EU students are generally not allowed to work on a student permit, apart from limited approved internships</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Cyprus Migration Department and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university. Applications from outside the EU are also processed through the Ministry of Education''s higher education services for entry approval.</p><ul><li>Academic transcripts and certificates, with translations</li><li>English proficiency proof</li><li>Personal statement and references for Master''s programmes</li><li>Portfolio or interview for some programmes</li><li>Passport copy and photographs</li><li>Proof of tuition payment for the visa</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition depends on the university and programme. Private universities charge higher fees than public universities.</p><ul><li>Tuition: roughly €4,000-€15,000 a year (estimate; medicine and some professional programmes cost more)</li><li>Living costs: about €700-€1,100 a month; Nicosia and Limassol are more expensive</li><li>Residence permit and registration: about €140-€200</li><li>Health insurance: about €150-€350 a year (reported)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with good results</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>English:</strong> IELTS 5.5-6.5 or equivalent for English-taught programmes</li><li>Some programmes ask for an interview or portfolio</li></ul>' WHERE slug = 'cyprus';
UPDATE countries SET why_title = 'Why study in Malta?', why_body = '<p>Malta is an English-speaking EU country with a Mediterranean climate and a compact, safe island setting. Its strengths include tourism and hospitality, finance, gaming and health programmes.</p><ul><li>English is an official language and the language of instruction</li><li>EU-recognised degrees at the University of Malta and other institutions</li><li>Strong tourism, finance and iGaming sectors</li><li>Easy access to Southern Europe</li></ul>', visa_title = 'Student visa and residence permit', visa_body = '<p>Non-EU students need a <strong>long-stay national student visa (D-visa)</strong> before travelling. Students staying for a year or more also apply for an <strong>e-Residence permit</strong> from Identità after arrival.</p><ul><li>Admission letter and proof of tuition payment</li><li>Proof of funds that meets Identità''s income threshold</li><li>Health insurance (a minimum cover of €100,000 is reported for many applicants)</li><li>Residence permit: apply within 90 days of arrival (University of Malta guidance)</li><li>Work: non-EU students need a Jobsplus licence and may work up to 20 hours a week, with some sources adding a 13-week waiting period</li><li>Visa fees: a government bill proposes higher service fees from 2027 (proposal, not confirmed)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Identità Malta and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each institution. The University of Malta has set application periods for international students.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof</li><li>Personal statement and CV for postgraduate programmes</li><li>Letters of recommendation for some programmes</li><li>Passport copy and photographs</li><li>Proof of tuition payment for the visa</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition depends on the institution and programme. The EU study portal gives general ranges for Malta.</p><ul><li>Tuition: Bachelor''s about €1,000-€9,000 a year and Master''s about €2,000-€12,000 a year (reported ranges; non-EU rates are higher)</li><li>Living costs: about €800-€1,300 a month; rent is the main cost</li><li>Health insurance is required</li><li>Residence permit and visa costs vary</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the institution and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects and grades</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>English:</strong> IELTS 6.0-6.5 or equivalent for most programmes</li><li>Some programmes ask for an interview or portfolio</li></ul>' WHERE slug = 'malta';
UPDATE countries SET why_title = 'Why study in Lithuania?', why_body = '<p>Lithuania is an EU and Eurozone country with low costs, English-taught degrees and strong programmes in health sciences, laser technology, business and IT. Vilnius is a modern, student-friendly capital.</p><ul><li>English-taught Bachelor''s and Master''s programmes, including medicine and dentistry</li><li>Lower tuition and living costs than most Western European countries</li><li>Strong in health sciences, laser and life-science research, and IT</li><li>Work options during studies for non-EU students</li></ul>', visa_title = 'Residence permit requirements', visa_body = '<p>Non-EU degree students need a <strong>Temporary Residence Permit (TRP)</strong> for study, applied for through a Lithuanian embassy or visa centre. Exchange students use a D-type visa instead.</p><ul><li>Admission letter and proof of tuition payment from a Lithuanian university</li><li>Proof of funds: Vilnius University''s 2026 checklist totals €8,077 for a year (0.5 times the minimum wage per month for 12 months plus an extra amount); other universities may use slightly different amounts</li><li>Bank statements for the last 6 months, in your name or your parents'' name</li><li>Health insurance valid for the permit period, accommodation proof and criminal record certificate</li><li>State fee: €160 (€320 for the urgent procedure)</li><li>Work: students may work with an employment contract (reported limits are 20 hours a week in the first two Bachelor''s years and 40 hours from year 3)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Lithuanian Migration Department (migracija.lt) site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university, or through the national application system (LAMA BPO) for some Bachelor''s programmes.</p><ul><li>Academic transcripts and certificates, apostilled</li><li>English proficiency proof</li><li>Motivation letter and CV for Master''s programmes</li><li>Entrance exams for medicine and some other programmes</li><li>Passport copy and photographs</li><li>Application fee at some universities</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition depends on the university and programme. Medicine and dentistry cost more than other fields.</p><ul><li>Tuition: roughly €2,000-€6,000 a year for many programmes (estimate); medicine often €10,000 or more</li><li>Living costs: about €500-€900 a month; Vilnius is more expensive than other cities</li><li>Residence permit fee: €160</li><li>Health insurance is required</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with good results; medicine needs biology and chemistry exams</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>English:</strong> IELTS 5.5-6.5 or equivalent</li><li>Applicants must show funds and health insurance for the permit</li></ul>' WHERE slug = 'lithuania';
UPDATE countries SET why_title = 'Why study in Latvia?', why_body = '<p>Latvia is an EU country with affordable English-taught programmes, especially in medicine, dentistry, engineering and business. Riga is a historic and lively capital with a large international student community.</p><ul><li>English-taught medicine and dentistry programmes with EU-recognised degrees</li><li>Lower tuition and living costs than many EU countries</li><li>Strong IT and engineering programmes</li><li>Central Baltic location</li></ul>', visa_title = 'Residence permit requirements', visa_body = '<p>Non-EU students need a <strong>residence permit for study</strong> from the Office of Citizenship and Migration Affairs (PMLP), usually applied for with the university''s help.</p><ul><li>Admission letter and signed study agreement from an accredited institution</li><li>Tuition for the full first year must be paid before applying (University of Latvia guidance), and the permit covers only the paid period</li><li>Proof of funds: guides report about €500-€600 a month, but figures differ, so confirm with PMLP</li><li>Health insurance valid in Latvia, passport and photographs</li><li>Criminal record certificate and accommodation proof</li><li>Fee: PMLP sets the fee; Master''s and doctoral students may be exempt from some charges (reported)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official PMLP (pmlp.gov.lv) site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university through its international admissions portal.</p><ul><li>Academic transcripts and certificates, apostilled</li><li>English proficiency proof</li><li>Motivation letter and CV for Master''s programmes</li><li>Entrance exams for medicine and dentistry</li><li>Passport copy and photographs</li><li>Application fee at some universities</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition depends on the university and programme. Medicine and dentistry cost more than other fields.</p><ul><li>Tuition: roughly €2,000-€6,000 a year for many programmes (estimate); medicine often €10,000 or more</li><li>Living costs: about €500-€800 a month; Riga is more expensive</li><li>Health insurance is required</li><li>First-year tuition is paid before the residence permit application</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with good results; medicine needs biology and chemistry</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>English:</strong> IELTS 5.5-6.5 or equivalent</li><li>Some programmes require entrance exams or interviews</li></ul>' WHERE slug = 'latvia';
UPDATE countries SET why_title = 'Why study in Estonia?', why_body = '<p>Estonia is known as one of the world''s most digital societies. Its universities offer English-taught degrees in IT, cyber security, engineering, business and the sciences, with a high quality of life.</p><ul><li>Leading digital and e-government country, strong for IT and cyber security</li><li>English-taught Bachelor''s and Master''s programmes</li><li>University of Tartu and TalTech are among the top universities in the Baltics</li><li>Low costs for an EU country</li></ul>', visa_title = 'Residence permit requirements', visa_body = '<p>Non-EU students need a <strong>temporary residence permit for study</strong> from the Estonian Police and Border Guard Board (PPA), applied for with the university''s admission documents.</p><ul><li>Admission letter from an Estonian institution</li><li>Proof of funds: sources report between about €350 and €900 a month, so check the current PPA amount</li><li>Health insurance, passport and photographs</li><li>The permit can end about 30 days after you interrupt or fall behind in your studies (PPA student guide, January 2026)</li><li>Work: students may work in Estonia as long as the work does not hinder their studies (check current rules)</li><li>Graduates may be able to stay for a period to look for work (check the current length)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official PPA (politsei.ee) site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Most universities use the national <strong>DreamApply</strong> platform or their own admission portal. Deadlines are usually in the spring for autumn study.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof</li><li>Motivation letter and CV</li><li>Letters of recommendation for some Master''s programmes</li><li>Entrance tests or interviews for some programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition depends on the university and programme. Many programmes charge tuition for non-EU students.</p><ul><li>Tuition: roughly €3,000-€7,000 a year for many programmes (estimate; check each university)</li><li>Living costs: about €500-€800 a month; Tallinn is more expensive than Tartu</li><li>Health insurance is required</li><li>Dora Plus and university fee waivers may help with costs</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with good results; some programmes ask for maths or entrance exams</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>English:</strong> IELTS 6.0-6.5 or equivalent for most programmes</li><li>Some programmes use interviews or portfolios</li></ul>' WHERE slug = 'estonia';
COMMIT;
